function trail(n: <number>): <text> {
  if n <= 0 {
    return "end"
  }
  rest = trail(n - 1)
  return CONCAT("${n}", ",", rest)
}
movement m(msg: <inbox-[:message]->>) {
  x = trail(3)
  write crm-[:notes]-> { body: x }
}

