import { email, attio } from adapters
import { dealflow_inbox, acme_main } from credentials
inbox = email(credentials: dealflow_inbox)
crm   = attio(credentials: acme_main)
node Co: "each company named" {
  name: <text> "its name"
  stage: <text> "its stage"
}
type Tier = <"gold" | "silver">

movement hp(r: <crm-[:company]->>) {
  write crm-[:notes]-> { body: r.name }
}
movement m(msg: <inbox-[:message]->>) {
  org = write crm-[:companies]-> { name: "Org" }
  c = () => IF msg.`subject` = "nope" THEN org ELSE "x" END
  w = c()
  hp(r: w)
}

import { email, attio } from adapters
import { dealflow_inbox, acme_main } from credentials
inbox = email(credentials: dealflow_inbox)
crm = attio(credentials: acme_main)
movement m(msg: <inbox-[:message]->>) {
  body = (x: <text>) => {
    await sleep(1h)
    return x
  }
  captured = "c"
  y = body("q")
  write crm-[:notes]-> { body: CONCAT(y, "/", captured) }
}

import { email, attio } from adapters
import { dealflow_inbox, acme_main } from credentials
inbox = email(credentials: dealflow_inbox)
crm = attio(credentials: acme_main)
movement m(msg: <inbox-[:message]->>) {
  r = await parallel([
    () => {
      a = write crm-[:companies]-> { name: "arm 0" }
      await sleep(1h)
      return a
    },
    () => 2
  ])
  h = AT(r, 0)
  write crm-[:notes]-> { body: CONCAT(COALESCE(AT(r, 0).name, "none"), "/", COALESCE(h.name, "none"), "/", IF AT(r, 0) == null THEN "missing" ELSE "held" END, "/", AT(r, 1)) }
}

